-- Modify "auth_browser_sessions" table
ALTER TABLE "auth_browser_sessions" ADD COLUMN "browser_context_id" character varying NULL, ADD COLUMN "browser_generation" bigint NULL;
-- Create "auth_browser_contexts" table
CREATE TABLE "auth_browser_contexts" ("id" character varying NOT NULL, "generation" bigint NOT NULL DEFAULT 0, "expires_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "browsercontext_expires_at" to table: "auth_browser_contexts"
CREATE INDEX "browsercontext_expires_at" ON "auth_browser_contexts" ("expires_at");
-- Create "oauth_browser_states" table
CREATE TABLE "oauth_browser_states" ("id" character varying NOT NULL, "usersrv_challenge_id" character varying NOT NULL, "state_hash" character varying NOT NULL, "provider" character varying NOT NULL, "intent" character varying NOT NULL, "browser_binding_hash" character varying NOT NULL, "browser_context_id" character varying NOT NULL, "browser_generation" bigint NOT NULL, "initiating_token_hash" character varying NOT NULL, "session_id" character varying NULL, "user_id" character varying NULL, "auth_version" bigint NULL, "provider_config_version" bigint NOT NULL, "context_hash" bytea NOT NULL, "nonce_hash" character varying NOT NULL, "key_id" character varying NOT NULL, "pkce_verifier_ciphertext" bytea NULL, "return_app_id" character varying NOT NULL, "return_path" character varying NOT NULL, "created_at" timestamptz NOT NULL, "expires_at" timestamptz NOT NULL, "consumed_at" timestamptz NULL, "result_status" character varying NOT NULL DEFAULT 'issued', "final_claimed_at" timestamptz NULL, "final_mutation_id" character varying NULL, "final_request_hash" character varying NULL, "confirmation_expires_at" timestamptz NULL, PRIMARY KEY ("id"), CONSTRAINT "oauth_state_binding" CHECK ((octet_length(context_hash) = 32) AND (length((state_hash)::text) = 64) AND (length((browser_binding_hash)::text) = 64) AND (length((nonce_hash)::text) = 64) AND (length((initiating_token_hash)::text) = 64)), CONSTRAINT "oauth_state_generation" CHECK ((browser_generation >= 0) AND (provider_config_version > 0)), CONSTRAINT "oauth_state_intent" CHECK ((intent)::text = ANY ((ARRAY['login'::character varying, 'link'::character varying])::text[])), CONSTRAINT "oauth_state_link_session" CHECK (((intent)::text <> 'link'::text) OR ((session_id IS NOT NULL) AND (user_id IS NOT NULL) AND (auth_version IS NOT NULL) AND (auth_version > 0))), CONSTRAINT "oauth_state_provider" CHECK ((provider)::text = ANY ((ARRAY['google'::character varying, 'github'::character varying])::text[])), CONSTRAINT "oauth_state_status" CHECK ((result_status)::text = ANY ((ARRAY['issued'::character varying, 'exchanging'::character varying, 'registration_pending'::character varying, 'link_pending'::character varying, 'registering'::character varying, 'authenticated'::character varying, 'failed'::character varying])::text[])));
-- Create index "oauth_browser_states_state_hash_key" to table: "oauth_browser_states"
CREATE UNIQUE INDEX "oauth_browser_states_state_hash_key" ON "oauth_browser_states" ("state_hash");
-- Create index "oauth_browser_states_usersrv_challenge_id_key" to table: "oauth_browser_states"
CREATE UNIQUE INDEX "oauth_browser_states_usersrv_challenge_id_key" ON "oauth_browser_states" ("usersrv_challenge_id");
-- Create index "oauthbrowserstate_expires_at" to table: "oauth_browser_states"
CREATE INDEX "oauthbrowserstate_expires_at" ON "oauth_browser_states" ("expires_at");
